-- EraLens period import: yuan-ming-qing
-- Window: 1271-12 .. 1912-02
BEGIN;

DELETE FROM event_dynasties WHERE event_id = 'qing-enter-pass';
DELETE FROM event_dynasties WHERE event_id = 'zheng-recover-taiwan' AND dynasty_id = 'ming-south';
DELETE FROM event_dynasties WHERE event_id = 'lu-jian-enthroned';
DELETE FROM event_participants WHERE event_id = 'lu-jian-enthroned';
DELETE FROM events WHERE id = 'lu-jian-enthroned';
DELETE FROM event_dynasties WHERE dynasty_id = 'yuan-north';
DELETE FROM event_participants WHERE event_id = 'yuan-north-end';
DELETE FROM events WHERE id = 'yuan-north-end';
DELETE FROM reigns WHERE dynasty_id = 'yuan-north';
DELETE FROM dynasties WHERE id = 'yuan-north';
-- remove stale auto-generated 史料缺 (两都之战并行叠放、驾崩至即位短空档应留白)
DELETE FROM reigns WHERE dynasty_id IN ('yuan') AND person_id = 'system-missing-ruler';
DELETE FROM relations WHERE id IN ('rel-yeshuntuemur-ragibagh-succession', 'rel-ragibagh-tugh-temur-succession', 'rel-khoshila-irinchibal-succession');
DELETE FROM reigns WHERE id = 'reign-puyi-qing-forbidden';
DELETE FROM event_participants WHERE event_id = 'puyi-leaves-forbidden-city';
DELETE FROM event_dynasties WHERE event_id = 'puyi-leaves-forbidden-city';
DELETE FROM events WHERE id = 'puyi-leaves-forbidden-city';
DELETE FROM events WHERE id = 'qing-moves-capital-to-beijing';
DELETE FROM event_participants WHERE event_id = 'shaowu-enthroned';
DELETE FROM event_dynasties WHERE event_id = 'shaowu-enthroned';
DELETE FROM events WHERE id = 'shaowu-enthroned';

