VALUES ('zhu-yuanzhang', '朱元璋', ARRAY[]::text[], NULL, NULL, NULL, NULL, NULL, NULL, ARRAY['皇帝'], '出身濠州贫苦农家，参加郭子兴领导的红巾军后崛起，攻占集庆并经营应天；鄱阳湖之战击败陈友谅，继而平定江南诸势力。1368年称帝建立明朝，定都南京；在位期间整饬吏治、编制黄册鱼鳞图册，并废丞相以强化中央集权。', '[{"label":"维基百科","url":"https://zh.wikipedia.org/wiki/朱元璋"}]'::jsonb, '高皇帝', '太祖', '明太祖')
